<?php
namespace Tests\Feature;
use Tests\TestCase;
use App\Models\{User,TikTokCuenta,TikTokComentario,TikTokTelegramConfig as Config,TikTokTelegramEnvio as Envio};
use App\Services\{TikTokRegistro,TikTokConsulta,TikTokTelegram};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Storage,Queue,Http,DB};
use Illuminate\Support\Str;
use Illuminate\Http\Client\ConnectionException;
class TikTokTelegramTest extends TestCase {
 use RefreshDatabase;
 private TikTokCuenta $c;private string $token='123456789:abcdefghijklmnopqrstuvwxyzABCDEFGHIJK';
 protected function setUp(): void {parent::setUp();Storage::fake('local');Queue::fake();Http::preventStrayRequests();$this->withoutMiddleware([\App\Http\Middleware\CorreoVerificado::class,\App\Http\Middleware\AceptaTerminos::class]);$this->actingAs(User::create(['usuario'=>'telegram_admin','name'=>'Administrador','email'=>'telegram@example.test','rol'=>'admin','activo'=>true,'password'=>'Prueba123456']));$this->c=TikTokCuenta::create(['usuario'=>'perfil_publico','monitorear'=>true,'estado'=>'pendiente']);$this->travelTo(now()->startOfMinute());}
 private function configurar(): Config {$cfg=Config::actual();$cfg->update(['bot_token'=>$this->token,'chat_id'=>Config::DESTINO,'activo'=>true,'verificada_en'=>now(),'chat_tipo'=>'private']);return $cfg->fresh();}
 private function capturar(string $id='evento1',string $texto='Comentario público 😀',?TikTokCuenta $cuenta=null): TikTokComentario {$c=$cuenta??$this->c;$n=TikTokConsulta::ahora();app(TikTokRegistro::class)->registrar($c,[['v'=>1,'tipo'=>'inicio','capturado_ms'=>$n,'sala'=>'7999999999999999999'],['v'=>1,'tipo'=>'comentario','capturado_ms'=>$n,'ocurrido_ms'=>$n,'sala'=>'7999999999999999999','id'=>$id,'autor'=>'participante','nombre'=>'Nombre público','texto'=>$texto,'publico'=>['usuario'=>'participante','usuario_sala'=>'sala_origen','id_usuario'=>'7000000000000000001','id_evento_fuente'=>'tiktok']]]);return $c->comentarios()->latest('id')->firstOrFail();}
 public function test_desactivado_no_crea_salidas_y_nunca_envia_durante_la_captura(): void {$this->capturar();$this->assertSame(0,Envio::count());$this->configurar();$this->capturar('evento2');$this->assertSame(1,Envio::count());Http::assertNothingSent();}
 public function test_un_mensaje_plano_con_nombre_usuario_sala_hora_id_y_sin_foto(): void {$this->configurar();$m=$this->capturar();Http::fake(['*'=>Http::response(['ok'=>true,'result'=>['message_id'=>42]],200)]);$this->assertTrue(app(TikTokTelegram::class)->procesarUno());$e=Envio::first();$this->assertSame('enviado',$e->estado);$this->assertSame('42',$e->mensaje_id);Http::assertSentCount(1);Http::assertSent(fn($r)=>str_ends_with($r->url(),'/sendMessage')&&$r['chat_id']===Config::DESTINO&&str_contains($r['text'],'Nombre: Nombre público')&&str_contains($r['text'],'Usuario: @participante')&&str_contains($r['text'],'Chat de origen: @sala_origen')&&str_contains($r['text'],'7999999999999999999')&&str_contains($r['text'],'Hora registrada:')&&str_contains($r['text'],$m->texto)&&!isset($r['photo'])&&!isset($r['parse_mode'])&&$r['link_preview_options']['is_disabled']===true);}
 public function test_evento_de_la_misma_sala_no_se_duplica_entre_perfiles(): void {$this->configurar();$this->capturar();$this->capturar();$otro=TikTokCuenta::create(['usuario'=>'otro_perfil','monitorear'=>true]);$this->capturar('evento1','Mismo evento',$otro);$this->assertSame(2,TikTokComentario::count());$this->assertSame(1,Envio::count());}
 public function test_alcance_seleccionado_no_envia_otros_perfiles_y_pausa_cancela_pendientes(): void {$cfg=$this->configurar();$cfg->update(['alcance'=>'seleccionadas','cuentas'=>[9999]]);$this->capturar();$this->assertSame(0,Envio::count());$cfg->update(['cuentas'=>[$this->c->id]]);$this->capturar('evento2');$this->assertSame(1,Envio::count());$this->c->update(['monitorear'=>false]);$this->assertFalse(app(TikTokTelegram::class)->procesarUno());$this->assertSame('cancelado',Envio::first()->estado);Http::assertNothingSent();}
 public function test_respeta_429_y_no_hace_peticiones_durante_la_espera(): void {$this->configurar();$this->capturar();Http::fake(['*'=>Http::sequence()->push(['ok'=>false,'error_code'=>429,'parameters'=>['retry_after'=>60]],429)->push(['ok'=>true,'result'=>['message_id'=>43]],200)]);$s=app(TikTokTelegram::class);$this->assertTrue($s->procesarUno());$this->assertSame('pendiente',Envio::first()->estado);$this->assertTrue(Config::actual()->no_antes_de->gte(now()->addSeconds(60)));$this->assertFalse($s->procesarUno());Http::assertSentCount(1);$this->travel(62)->seconds();$this->assertTrue($s->procesarUno());$this->assertSame('enviado',Envio::first()->estado);Http::assertSentCount(2);}
 public function test_fallo_de_red_no_reintenta_un_envio_sin_confirmacion_ni_expone_token(): void {$this->configurar();$this->capturar();Http::fake(fn()=>throw new ConnectionException('URL secreta '.$this->token));$s=app(TikTokTelegram::class);$this->assertTrue($s->procesarUno());$this->assertSame('indeterminado',Envio::first()->estado);$this->assertStringNotContainsString($this->token,Envio::first()->detalle);$this->travel(10)->seconds();$this->assertFalse($s->procesarUno());$this->assertTrue($this->c->fresh()->monitorear);}
 public function test_rechazo_del_bot_pausa_solo_telegram_y_conserva_comentarios(): void {$this->configurar();$this->capturar();Http::fake(['*'=>Http::response(['ok'=>false,'error_code'=>401],401)]);app(TikTokTelegram::class)->procesarUno();$this->assertFalse(Config::actual()->activo);$this->assertTrue($this->c->fresh()->monitorear);$this->assertSame(1,TikTokComentario::count());$this->assertSame('fallido',Envio::first()->estado);}
 public function test_mensaje_largo_se_recorta_en_un_solo_envio_y_conserva_original(): void {$this->configurar();$m=$this->capturar('largo',str_repeat('😀',4000));$texto=app(TikTokTelegram::class)->texto($m->load(['live','cuenta']));$this->assertLessThanOrEqual(4096,intdiv(strlen(mb_convert_encoding($texto,'UTF-16LE','UTF-8')),2));$this->assertStringContainsString('Texto recortado para Telegram',$texto);$this->assertSame(4000,mb_strlen($m->fresh()->texto));}
 public function test_token_cifrado_no_se_muestra_ni_se_guarda_en_old_input(): void {$cfg=$this->configurar();$this->assertNotSame($this->token,DB::table('tiktok_telegram_config')->value('bot_token'));$this->assertArrayNotHasKey('bot_token',$cfg->toArray());$this->get(route('admin.tiktok.telegram.index'))->assertOk()->assertDontSee($this->token,false);$this->post(route('admin.tiktok.telegram.guardar'),['telegram_token'=>$this->token,'chat_id'=>'invalido','alcance'=>'todas'])->assertSessionHasErrors('chat_id');$this->assertArrayNotHasKey('telegram_token',session('_old_input',[]));}
 public function test_destino_es_fijo_y_no_permite_otros_usuarios_ni_grupos(): void {
  $cfg=$this->configurar();$this->capturar();foreach(['12345678','-1001234567890','@otro_usuario']as$id)$this->post(route('admin.tiktok.telegram.guardar'),['chat_id'=>$id,'alcance'=>'todas'])->assertSessionHasErrors('chat_id');
  $this->assertSame(Config::DESTINO,Config::actual()->chat_id);Http::assertNothingSent();
  // Incluso una alteración directa del registro no permite enviar a otro chat.
  $cfg->refresh()->update(['chat_id'=>'12345678']);$this->assertFalse(app(TikTokTelegram::class)->procesarUno());$this->assertSame('cancelado',Envio::first()->estado);Http::assertNothingSent();
 }
 public function test_verificar_bot_y_chat_no_envia_mensajes_y_activacion_requiere_verificacion(): void {$cfg=$this->configurar();$cfg->update(['activo'=>false,'verificada_en'=>null]);$this->post(route('admin.tiktok.telegram.activar'),['activo'=>1])->assertSessionHasErrors('telegram');Http::fake(['*/getMe'=>Http::response(['ok'=>true,'result'=>['is_bot'=>true,'username'=>'bot_prueba']],200),'*/getChat'=>Http::response(['ok'=>true,'result'=>['type'=>'private','id'=>Config::DESTINO]],200)]);$this->post(route('admin.tiktok.telegram.verificar'))->assertRedirect()->assertSessionHasNoErrors();$this->assertNotNull(Config::actual()->verificada_en);Http::assertSentCount(2);$this->post(route('admin.tiktok.telegram.activar'),['activo'=>1])->assertRedirect()->assertSessionHasNoErrors();$this->assertTrue(Config::actual()->activo);Http::assertSentCount(2);}
 public function test_trabajador_desactivado_no_hace_peticiones_y_registro_alterado_no_se_envia(): void {
  $this->artisan('micv:tiktok-telegram',['--una-vez'=>true])->assertSuccessful();Http::assertNothingSent();$this->configurar();$m=$this->capturar();$m->update(['texto'=>'Cambio fuera de la captura']);$this->assertTrue(app(TikTokTelegram::class)->procesarUno());$this->assertSame('fallido',Envio::first()->estado);Http::assertNothingSent();
 }
 public function test_interrupcion_de_un_envio_no_provoca_duplicacion_automatica_al_reiniciar(): void {
  $this->configurar();$this->capturar();Envio::first()->update(['estado'=>'enviando','iniciado_en'=>now()->subMinutes(2)]);$this->assertFalse(app(TikTokTelegram::class)->procesarUno());$this->assertSame('indeterminado',Envio::first()->estado);Http::assertNothingSent();
 }
 public function test_credenciales_y_destino_solo_accesibles_a_admin(): void {$u=User::create(['usuario'=>'no_admin_tg','name'=>'Usuario','email'=>'noadmin@example.test','rol'=>'cliente','activo'=>true,'password'=>'Prueba123456']);$this->actingAs($u)->get(route('admin.tiktok.telegram.index'))->assertForbidden();$this->post(route('admin.tiktok.telegram.guardar'),['chat_id'=>'123'])->assertForbidden();}
}
